#include <stdlib.h>

int main() {
    // Exemple de fuite de mémoire
    int *leak = (int*)malloc(sizeof(int) * 10);
    // Mémoire non libérée
    return 0;
}

invalidAccess.example:
#include <stdlib.h>

int main() {
    // Exemple de lecture/écriture invalide
    int *arr = (int*)malloc(sizeof(int) * 5);
    arr[5] = 10;  // Hors limites
    free(arr);
    return 0;
}

uninitializedValue.example:
#include <stdio.h>

int main() {
    int x;  // Non initialisée
    if (x > 0) {  // Utilisation de valeur non initialisée
        printf("Positif\n");
    }
    return 0;
}

doubleFree.example:
#include <stdlib.h>

int main() {
    int *ptr = (int*)malloc(sizeof(int));
    free(ptr);
    free(ptr);  // Double libération
    return 0;
}

mismatchedFree.example:
#include <stdlib.h>

int main() {
    int *arr = (int*)malloc(10 * sizeof(int));
    delete[] arr;  // Mauvaise fonction
    return 0;
}

overlappingMemory.example:
#include <string.h>

int main() {
    char str[20] = "Bonjour !";
    memcpy(str + 5, str, 10);  // Chevauchement
    return 0;
}
